#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the cutover of appliedailetter.com from IONOS DNS to a Cloudflare
# Worker, in the rollout order of the spec. Run from anywhere:
#
#   tools/cloudflare-setup.sh            # start at stage 1
#   tools/cloudflare-setup.sh --from 4   # resume at stage 4 (DNS can take hours)
#
# Rules this wizard keeps:
#   - No secret is ever written to disk or put on a command line. The shared
#     secret is generated in memory, copied to the clipboard for the AWS
#     console, and piped to `wrangler secret put` on stdin.
#   - ENV_FILE is /dev/null and write_env is never called.
#   - Every step that changes something live asks y/N first. Backend (SAM)
#     deploys and the Secrets Manager edit are only printed, never run here.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
ENV_FILE=/dev/null

DOMAIN="appliedailetter.com"
AWS_PROFILE_NAME="newsletter"
AWS_REGION_NAME="us-east-2"
STACK_NAME="newsletter"
SECRET_ID="applied-ai-letter/stripe"
BACKUP_DIR="$HOME/Desktop/Github/_backups"
SCRIPT_PATH="$0"
REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WRANGLER=(npx --yes wrangler@4)   # `npx wrangler` with a pinned major; --yes keeps npx from prompting on stdin
BACKEND_README="$REPO/../kitagrawal-newsletter/newsletter/api/README.md"

START=1
USE_AWS=0
DEFAULT_EXTRA="autodiscover s1-ionos._domainkey s2-ionos._domainkey _autodiscover._tcp"
SNAP=""
CF_NS1=""
CF_NS2=""
CANCEL_API_URL=""
SHARED_SECRET=""
WORKER_SECRETS=()

usage() {
  printf 'Usage: %s [--from N]\n  --from N  resume at stage N (1-%s)\n' "$0" "$TOTAL_STAGES"
}

while (( $# )); do
  case "$1" in
    --from) START="${2:-}"; shift 2 || { usage; exit 2; } ;;
    -h|--help) usage; exit 0 ;;
    *) usage; exit 2 ;;
  esac
done
if ! [[ "$START" =~ ^[1-9][0-9]*$ ]] || (( START > TOTAL_STAGES )); then usage; exit 2; fi

# ── helpers ───────────────────────────────────────────────────────────────

# gate "what is about to change" asks y/N; on No it stops cleanly so the run can resume here.
gate() {
  local n="$1" what="$2"
  if ! confirm "$what"; then
    warn "Stopped before this step. Nothing changed. Resume with: $SCRIPT_PATH --from $n"
    exit 0
  fi
}

# need CMD checks a tool exists.
need() { command -v "$1" >/dev/null 2>&1; }

# aws_ro runs a read-only AWS CLI call with the newsletter profile; only when the owner allowed it.
aws_ro() {
  (( USE_AWS )) || return 1
  aws --profile "$AWS_PROFILE_NAME" --region "$AWS_REGION_NAME" "$@" 2>/dev/null
}

# query_rec SERVER NAME TYPE prints "name|TYPE|answers", lower-cased, sorted, joined by ";".
# SERVER may be empty (system resolver).
query_rec() {
  local server="$1" name="$2" type="$3" ans
  local args=(+short +time=3 +tries=2)
  [[ -n "$server" ]] && args+=("@$server")
  ans=$( { dig "${args[@]}" "$name" "$type" || true; } | tr '[:upper:]' '[:lower:]' | sed 's/\.$//' | sort | paste -sd';' - )
  printf '%s|%s|%s\n' "$name" "$type" "$ans"
}

# record_set SERVER NAME TYPE... prints REC lines for NAME. A CNAME excludes other data and dig follows it for
# other types (a recursive resolver then adds the target's addresses), so a CNAME alone is recorded when present.
record_set() {
  local server="$1" name="$2" cn type; shift 2
  cn=$(query_rec "$server" "$name" CNAME)
  if [[ "${cn#*|*|}" != "" ]]; then printf 'REC|%s\n' "$cn"; return 0; fi
  printf 'REC|%s\n' "$cn"
  for type in "$@"; do printf 'REC|%s\n' "$(query_rec "$server" "$name" "$type")"; done
}

# Records whose job is the website; they change on purpose when the Worker takes over.
is_web_record() {
  local name="$1" type="$2"
  [[ "$name" == "$DOMAIN" || "$name" == "www.$DOMAIN" ]] && [[ "$type" == A || "$type" == AAAA || "$type" == CNAME ]]
}

# latest_snapshot sets SNAP to the newest snapshot file, or fails.
latest_snapshot() {
  [[ -n "$SNAP" && -f "$SNAP" ]] && return 0
  SNAP=$(ls -t "$BACKUP_DIR"/appliedailetter-dns-snapshot-*.txt 2>/dev/null | head -n1 || true)
  [[ -n "$SNAP" && -f "$SNAP" ]]
}

# compare_snapshot SERVER re-queries every snapshot record at SERVER and prints the differences.
# Returns the number of mail-critical mismatches (web records are informational only).
compare_snapshot() {
  local server="$1" line name type want got bad=0 shown
  while IFS= read -r line; do
    [[ "$line" == REC\|* ]] || continue
    line="${line#REC|}"
    name="${line%%|*}"; line="${line#*|}"; type="${line%%|*}"; want="${line#*|}"
    got=$(query_rec "$server" "$name" "$type"); got="${got#*|*|}"
    shown="${name} ${type}"
    if [[ "$got" == "$want" && -z "$want" ]]; then
      continue   # empty in both places: nothing to keep
    elif [[ "$got" == "$want" ]]; then
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$shown"
    elif is_web_record "$name" "$type"; then
      printf '  %sℹ%s %s differs (expected: the Worker replaces web records)\n' "$BLUE" "$RESET" "$shown"
      note "      was: ${want:-<none>}"; note "      now: ${got:-<none>}"
    else
      printf '  %s✗%s %s\n' "$RED" "$RESET" "$shown"
      note "      was: ${want:-<none>}"; note "      now: ${got:-<none>}"
      bad=$((bad + 1))
    fi
  done < "$SNAP"
  return "$bad"
}

# retry_compare SERVER loops compare_snapshot until clean or the owner skips.
retry_compare() {
  local server="$1" reply
  while ! compare_snapshot "$server"; do
    warn "Mail-critical records differ from the snapshot."
    note "Fix them in the Cloudflare DNS tab. DKIM CNAMEs must be 'DNS only' (grey cloud)."
    printf '  Press Enter to re-check, or type skip to continue anyway: '
    read -r reply || true
    [[ "$reply" == skip ]] && { warn "Continuing with differences. Check mail by hand."; return 0; }
  done
  say "All mail-critical records match the snapshot."
}

# http_check LABEL EXPECT_CODE [curl args...] prints the status and returns success when it matches.
http_check() {
  local label="$1" want="$2"; shift 2
  local code
  code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 20 "$@" 2>/dev/null || true)
  code="${code:-000}"
  if [[ "$code" == "$want" ]]; then printf '  %s✓%s %s → %s\n' "$GREEN" "$RESET" "$label" "$code"; return 0; fi
  printf '  %s✗%s %s → %s (wanted %s)\n' "$RED" "$RESET" "$label" "$code" "$want"; return 1
}

# curl_url URL [curl args...] passes the URL through stdin config so it never shows in `ps`.
curl_url() {
  local url="$1"; shift
  printf 'url = "%s"\n' "$url" | curl -sS --max-time 20 -K - "$@"
}

# secret_put NAME VALUE pipes VALUE to `wrangler secret put NAME` on stdin: nothing is echoed or written.
secret_put() {
  local name="$1" value="$2"
  if printf '%s' "$value" | (cd "$REPO" && "${WRANGLER[@]}" secret put "$name" >/dev/null 2>&1); then
    printf '  %s✓ set%s Worker secret %s\n' "$GREEN" "$RESET" "$name"
    WORKER_SECRETS+=("$name")
  else
    warn "wrangler could not set $name (not logged in? run: cd $REPO && npx wrangler login)"
    SKIPPED+=("Worker secret $name (npx wrangler secret put $name)")
  fi
}

cancel_function() {
  aws_ro cloudformation describe-stack-resource --stack-name "$STACK_NAME" --logical-resource-id CancelFunction \
    --query 'StackResourceDetail.PhysicalResourceId' --output text
}

preflight() {
  local missing=() t
  for t in dig curl openssl npx; do need "$t" || missing+=("$t"); done
  if (( ${#missing[@]} )); then
    warn "Missing tools: ${missing[*]}. Install them and re-run."
    exit 1
  fi
  need aws || note "aws CLI not found: AWS lookups will be asked of you instead."
  if need aws && confirm "May I run READ-ONLY aws lookups (profile $AWS_PROFILE_NAME, $AWS_REGION_NAME: SES identity, stack outputs, log search)?"; then
    USE_AWS=1
  fi
}

# ── stages ────────────────────────────────────────────────────────────────

stage_snapshot() {
  stage "Snapshot the current DNS (mail must not break)"
  say "Records for $DOMAIN are read with dig from the CURRENT authoritative server and saved outside the repo."
  local ns tokens t mailfrom extra e name type
  ns=$( { dig +short NS "$DOMAIN" || true; } | sed -n '1{s/\.$//;p;}')
  [[ -n "$ns" ]] || { warn "No NS found for $DOMAIN. Is the domain registered and delegated?"; exit 1; }
  say "Current authoritative server: $ns"

  tokens=""
  mailfrom=""
  if (( USE_AWS )); then
    tokens=$(aws_ro sesv2 get-email-identity --email-identity "$DOMAIN" --query 'DkimAttributes.Tokens' --output text || true)
    mailfrom=$(aws_ro sesv2 get-email-identity --email-identity "$DOMAIN" --query 'MailFromAttributes.MailFromDomain' --output text || true)
    [[ "$mailfrom" == None ]] && mailfrom=""
    [[ -n "$tokens" ]] && say "SES DKIM tokens read from AWS: $tokens"
  fi
  if [[ -z "$tokens" ]]; then
    note "SES console → Configuration → Identities → $DOMAIN → Authentication shows three DKIM CNAMEs."
    open_url "https://$AWS_REGION_NAME.console.aws.amazon.com/ses/home?region=$AWS_REGION_NAME#/identities/$DOMAIN"
    local t1="" t2="" t3=""
    ask t1 "DKIM token 1 (the part before ._domainkey):"
    ask t2 "DKIM token 2:"
    ask t3 "DKIM token 3:"
    tokens="$t1 $t2 $t3"
  fi
  if [[ -z "$mailfrom" ]]; then
    ask mailfrom "Custom MAIL FROM domain, if SES uses one (Enter for none):" || mailfrom=""
  fi
  note "dig cannot list a zone. Name any other hostnames whose records you need to keep"
  note "(a mail subdomain, a Cal.com or Stripe verification name). Enter alone checks the IONOS mail defaults:"
  note "  $DEFAULT_EXTRA"
  ask extra "Other hostnames, space separated (Enter for the defaults):" || extra=""
  [[ -n "$extra" ]] || extra="$DEFAULT_EXTRA"

  SNAP="$BACKUP_DIR/appliedailetter-dns-snapshot-$(date +%Y%m%d-%H%M%S).txt"
  mkdir -p "$BACKUP_DIR"
  {
    printf '# DNS snapshot of %s taken %s from %s (read with dig; no secrets)\n' "$DOMAIN" "$(date '+%Y-%m-%d %H:%M:%S %z')" "$ns"
    printf '# NS: %s\n' "$(dig +short NS "$DOMAIN" | tr '\n' ' ')"
    printf '# DS (DNSSEC): %s\n' "$(dig +short DS "$DOMAIN" | tr '\n' ' ')"
    for type in A AAAA MX TXT CAA; do printf 'REC|%s\n' "$(query_rec "$ns" "$DOMAIN" "$type")"; done
    record_set "$ns" "www.$DOMAIN" A AAAA
    record_set "$ns" "_dmarc.$DOMAIN" TXT
    record_set "$ns" "_amazonses.$DOMAIN" TXT
    for t in $tokens; do printf 'REC|%s\n' "$(query_rec "$ns" "$t._domainkey.$DOMAIN" CNAME)"; done
    if [[ -n "$mailfrom" ]]; then
      for type in MX TXT; do printf 'REC|%s\n' "$(query_rec "$ns" "$mailfrom" "$type")"; done
    fi
    for e in $extra; do
      name="$e"; [[ "$name" == *"$DOMAIN" ]] || name="$e.$DOMAIN"
      record_set "$ns" "$name" A AAAA TXT MX SRV
    done
  } > "$SNAP"

  printf '\n'
  grep '^#' "$SNAP" | while IFS= read -r l; do note "$l"; done
  grep '^REC|' "$SNAP" | awk -F'|' '$4 != "" { printf "  %s %s -> %s\n", $2, $3, $4 }' | cut -c1-150
  printf '\n'
  { grep -E '^REC\|[^|]*\._domainkey\.[^|]*\|CNAME\|$' "$SNAP" || true; } | while IFS='|' read -r _ name _; do
    warn "No answer for $name: wrong DKIM token, or that record is not in DNS."
  done
  say "Saved to $SNAP"
  warn "Check the snapshot has MX, SPF (v=spf1), DMARC and the three DKIM CNAMEs. A missing one means dig could not see it."
  note "Also open IONOS DNS and keep that page (or a screenshot) as the second source of truth."
  open_url "https://my.ionos.com/domains"
  pause "Snapshot looks right and IONOS DNS records are noted? Press Enter."
}

stage_add_zone() {
  stage "Cloudflare: add the zone and compare the imported records"
  latest_snapshot || { warn "No snapshot in $BACKUP_DIR. Run stage 1 first: $SCRIPT_PATH --from 1"; exit 1; }
  say "Using snapshot: $SNAP"
  open_url "https://dash.cloudflare.com/?to=/:account/add-site"
  step "Add a site → enter $DOMAIN → Free plan → Continue."
  step "Let Cloudflare scan, then open DNS → Records."
  step "Compare every record with the snapshot and the IONOS page. Add anything missing."
  step "Every DKIM CNAME, and any mail-related CNAME, must be 'DNS only' (grey cloud), not proxied."
  step "Leave the web records (A/AAAA for @ and www) for now; stage 5 replaces them."
  step "On the 'Update your nameservers' step, copy the two Cloudflare nameservers."
  ask CF_NS1 "Cloudflare nameserver 1 (xxx.ns.cloudflare.com):"
  ask CF_NS2 "Cloudflare nameserver 2:"
  CF_NS1=$(printf '%s' "$CF_NS1" | tr '[:upper:]' '[:lower:]' | sed 's/\.$//')
  CF_NS2=$(printf '%s' "$CF_NS2" | tr '[:upper:]' '[:lower:]' | sed 's/\.$//')
  [[ "$CF_NS1" == *.ns.cloudflare.com && "$CF_NS2" == *.ns.cloudflare.com ]] \
    || warn "Those do not look like Cloudflare nameservers (expected *.ns.cloudflare.com)."
  printf '\n'
  say "Checking the imported records directly on $CF_NS1 (nothing is delegated yet):"
  retry_compare "$CF_NS1"
  pause "Press Enter when the Cloudflare zone matches."
}

stage_switch_ns() {
  stage "IONOS: switch the nameservers to Cloudflare"
  latest_snapshot || { warn "No snapshot found. Run stage 1 first."; exit 1; }
  if [[ -z "$CF_NS1" ]]; then
    ask CF_NS1 "Cloudflare nameserver 1 (from the zone's Overview page):"
    ask CF_NS2 "Cloudflare nameserver 2:"
    CF_NS1=$(printf '%s' "$CF_NS1" | tr '[:upper:]' '[:lower:]' | sed 's/\.$//')
    CF_NS2=$(printf '%s' "$CF_NS2" | tr '[:upper:]' '[:lower:]' | sed 's/\.$//')
  fi
  local ds; ds=$(dig +short DS "$DOMAIN")
  if [[ -n "$ds" ]]; then
    warn "DNSSEC is on at the registry (DS record found). Turn DNSSEC OFF at IONOS first and wait for the old DS TTL,"
    warn "or Cloudflare-hosted answers will fail validation and the domain will look dead."
  fi
  warn "This is the live cutover: DNS for $DOMAIN (website AND mail) moves to Cloudflare."
  note "Rollback: put the old IONOS nameservers back (written down in the snapshot's NS line)."
  gate 3 "Switch the nameservers at IONOS now?"
  open_url "https://my.ionos.com/domains"
  step "IONOS → Domains & SSL → $DOMAIN → Nameservers → use custom nameservers."
  step "Enter: $CF_NS1 and $CF_NS2, replacing the IONOS ones. Save."
  step "Back in Cloudflare, click 'Done, check nameservers'."
  pause "Saved at IONOS? Press Enter to start watching for the change."

  say "Polling the delegation every 30s (Ctrl-C or q to stop; resume with --from 3)."
  local i ns_now ok=0 key=""
  for i in $(seq 1 120); do
    ns_now=$( { dig +short NS "$DOMAIN" @1.1.1.1 || true; } | sed 's/\.$//' | tr '[:upper:]' '[:lower:]' | sort | paste -sd' ' -)
    if [[ "$ns_now" == *"$CF_NS1"* && "$ns_now" == *"$CF_NS2"* ]]; then ok=1; break; fi
    printf '  [%s] still: %s\n' "$i" "${ns_now:-<no answer>}"
    key=""; read -r -s -n1 -t 30 key || true
    [[ "$key" == q ]] && break
  done
  if (( ! ok )); then
    warn "Not delegated yet. Registries can take hours. Resume later with: $SCRIPT_PATH --from 3"
    exit 0
  fi
  say "NS now: $ns_now"
  printf '\n'
  say "Re-checking mail records through 1.1.1.1:"
  retry_compare "1.1.1.1"
  if (( USE_AWS )); then
    local dk ver
    dk=$(aws_ro sesv2 get-email-identity --email-identity "$DOMAIN" --query 'DkimAttributes.Status' --output text || true)
    ver=$(aws_ro sesv2 get-email-identity --email-identity "$DOMAIN" --query 'VerifiedForSendingStatus' --output text || true)
    say "SES says: DKIM ${dk:-unknown}, verified for sending ${ver:-unknown} (SES can lag a few minutes)."
  fi
  pause "Press Enter to continue."
}

stage_secrets() {
  stage "Worker secrets (CANCEL_SHARED_SECRET, CANCEL_API_URL, SUBSCRIBE_URL)"
  say "Values go to Cloudflare through stdin. They are not echoed, not saved and not in the repo."
  if ! (cd "$REPO" && "${WRANGLER[@]}" whoami 2>/dev/null | grep -qi 'logged in'); then
    warn "wrangler is not logged in to Cloudflare."
    gate 4 "Run 'npx wrangler login' now (opens a browser for you to approve)?"
    (cd "$REPO" && "${WRANGLER[@]}" login) || { warn "Login did not finish."; exit 1; }
  fi

  # 1. shared secret
  printf '\n'
  step "1/3 CANCEL_SHARED_SECRET: one value in Secrets Manager AND the Worker."
  local mode
  printf '  Generate a new one, or paste the value you already added to AWS? [G/p] '
  read -r mode || true
  if [[ "$mode" =~ ^[Pp] ]]; then
    ask_secret SHARED_SECRET "Paste the existing secret value:"
  else
    SHARED_SECRET=$(openssl rand -hex 32)
    if need pbcopy; then
      printf '%s' "$SHARED_SECRET" | pbcopy
      say "A new 64-character secret is in your CLIPBOARD (not shown here)."
    else
      say "New secret (copy it now; it is shown once): $SHARED_SECRET"
    fi
    open_url "https://$AWS_REGION_NAME.console.aws.amazon.com/secretsmanager/secret?name=$(printf '%s' "$SECRET_ID" | sed 's#/#%2F#')&region=$AWS_REGION_NAME"
    note "Console path: Secrets Manager → region $AWS_REGION_NAME → $SECRET_ID → Retrieve secret value → Edit."
    step "Add a row: key CANCEL_SHARED_SECRET, value = paste. Keep STRIPE_SECRET_KEY and STRIPE_WEBHOOK_SECRET as they are. Save."
    pause "Saved in Secrets Manager? Press Enter."
    need pbcopy && { printf '' | pbcopy; note "Clipboard cleared."; }
  fi
  if (( USE_AWS )) && confirm "Verify the AWS field equals this value? (reads the secret JSON in memory and prints only yes/no)"; then
    local verdict
    verdict=$(aws_ro secretsmanager get-secret-value --secret-id "$SECRET_ID" --query SecretString --output text \
      | CHECK="$SHARED_SECRET" python3 -I -c 'import json,os,sys; d=json.loads(sys.stdin.read()); print("match" if d.get("CANCEL_SHARED_SECRET")==os.environ["CHECK"] else "MISSING or DIFFERENT")' 2>/dev/null || echo "could not read")
    say "Secrets Manager field: $verdict"
    [[ "$verdict" == match ]] || { warn "Fix the AWS field before going on."; pause "Press Enter once fixed."; }
  fi

  # 2. cancel API URL
  printf '\n'
  step "2/3 CANCEL_API_URL: the stack output CancelApiUrl."
  if (( USE_AWS )); then
    CANCEL_API_URL=$(aws_ro cloudformation describe-stacks --stack-name "$STACK_NAME" \
      --query "Stacks[0].Outputs[?OutputKey=='CancelApiUrl'].OutputValue" --output text || true)
    [[ "$CANCEL_API_URL" == None ]] && CANCEL_API_URL=""
    [[ -n "$CANCEL_API_URL" ]] && say "Read from the $STACK_NAME stack (not shown)."
  fi
  if [[ -z "$CANCEL_API_URL" ]]; then
    note "CloudFormation → stack $STACK_NAME → Outputs → CancelApiUrl."
    ask_secret CANCEL_API_URL "Paste CancelApiUrl:"
  fi
  [[ "$CANCEL_API_URL" == https://* ]] || warn "CANCEL_API_URL does not start with https://. Check it."

  # 3. subscribe URL
  printf '\n'
  step "3/3 SUBSCRIBE_URL: the Stripe Payment Link for the newsletter."
  open_url "https://dashboard.stripe.com/payment-links"
  local subscribe_url=""
  ask_secret subscribe_url "Paste the Payment Link (https://buy.stripe.com/...):"
  [[ "$subscribe_url" == https://buy.stripe.com/* ]] || warn "That is not a buy.stripe.com link. The /subscribe check in stage 5 will tell."

  printf '\n'
  gate 4 "Write these three secrets to the Cloudflare Worker '$(grep -o '"name": *"[^"]*"' "$REPO/wrangler.jsonc" | head -n1 | cut -d'"' -f4)' now (creates a draft Worker if none exists)?"
  secret_put CANCEL_SHARED_SECRET "$SHARED_SECRET"
  secret_put CANCEL_API_URL "$CANCEL_API_URL"
  secret_put SUBSCRIBE_URL "$subscribe_url"
  unset subscribe_url
  note "The shared secret stays in memory only for this run. If you stop now, re-run stage 4: it makes a new one and overwrites both sides."
  pause "Press Enter to continue."
}

stage_first_deploy() {
  stage "First deploy of the Worker, from this branch"
  local branch; branch=$(git -C "$REPO" branch --show-current 2>/dev/null || true)
  say "Repo: $REPO (branch: ${branch:-unknown})"
  [[ -z "$(git -C "$REPO" status --porcelain --untracked-files=no 2>/dev/null)" ]] || warn "Uncommitted changes to tracked files: the deploy uploads what is on disk."
  printf '\n'
  warn "Worker Custom Domains create their own DNS records. In Cloudflare → DNS → Records, delete the"
  warn "imported A/AAAA/CNAME records for $DOMAIN and www.$DOMAIN (GitHub Pages / IONOS parking). Keep MX, TXT, DKIM."
  open_url "https://dash.cloudflare.com/?to=/:account/:zone/dns/records"
  pause "Web records for @ and www deleted? Press Enter."
  gate 5 "Run 'npx wrangler deploy' now? This publishes the Worker and attaches $DOMAIN and www.$DOMAIN."
  (cd "$REPO" && "${WRANGLER[@]}" deploy) || { warn "Deploy failed. Read the error above, fix, and re-run: $SCRIPT_PATH --from 5"; exit 1; }

  printf '\n'
  say "Live checks (a new custom domain can take a minute to get its certificate):"
  local n ok=0
  for n in 1 2 3 4 5 6 7 8; do
    if http_check "https://$DOMAIN/" 200 "https://$DOMAIN/"; then ok=1; break; fi
    note "waiting 15s (attempt $n/8)"; sleep 15
  done
  (( ok )) || warn "The home page is not up yet. Check Workers & Pages → appliedailetter → Domains."
  http_check "/subscribe redirects" 302 "https://$DOMAIN/subscribe" || true
  local loc; loc=$(curl -sS -o /dev/null -w '%{redirect_url}' --max-time 20 "https://$DOMAIN/subscribe" 2>/dev/null || true)
  case "$loc" in
    https://buy.stripe.com/*) printf '  %s✓%s /subscribe → buy.stripe.com\n' "$GREEN" "$RESET" ;;
    *) printf '  %s✗%s /subscribe goes to %s (wanted https://buy.stripe.com/...)\n' "$RED" "$RESET" "${loc:-<nowhere>}" ;;
  esac
  http_check "www redirects to the apex" 301 "https://www.$DOMAIN/" || true
  loc=$(curl -sS -o /dev/null -w '%{redirect_url}' --max-time 20 "https://www.$DOMAIN/" 2>/dev/null || true)
  [[ "$loc" == "https://$DOMAIN/" ]] && printf '  %s✓%s www → %s\n' "$GREEN" "$RESET" "$loc" || printf '  %s✗%s www goes to %s\n' "$RED" "$RESET" "${loc:-<nowhere>}"
  local body
  body=$(curl -sS --max-time 20 -X POST -H 'content-type: application/json' --data '{"c":"cus_invalid"}' "https://$DOMAIN/api/cancel" 2>/dev/null || true)
  if [[ "$body" == *'"error"'* ]]; then
    printf '  %s✓%s POST /api/cancel with a fake id → %s\n' "$GREEN" "$RESET" "$body"
  else
    printf '  %s✗%s POST /api/cancel did not return JSON with "error": %s\n' "$RED" "$RESET" "${body:-<empty>}"
  fi
  note "That POST reached the live cancel API with a fake customer id; it changes nothing."
  pause "Press Enter to continue."
}

stage_backend_warn() {
  stage "Backend deploy 1 (warn mode): you run this, I only print it"
  say "The cancel Lambda starts logging calls without the X-Cancel-Secret header and serves them anyway."
  say "It also moves the Unsubscribe link base to https://$DOMAIN. Full notes: $BACKEND_README"
  printf '\n'
  note "# the branch must be python-stack (local, never pushed); the worktree is ../kitagrawal-newsletter"
  note "cd $REPO/../kitagrawal-newsletter/newsletter/api"
  note "sam build"
  note "sam deploy --profile $AWS_PROFILE_NAME --region $AWS_REGION_NAME --stack-name $STACK_NAME --resolve-s3 --capabilities CAPABILITY_IAM \\"
  note "  --no-execute-changeset \\"
  note "  --parameter-overrides 'FromAddress=\"The Applied AI Letter <letters@$DOMAIN>\"' SesDomain=$DOMAIN CreateSesIdentity=false NewsletterProductId=prod_..."
  note "# read the changeset, then run the same command without --no-execute-changeset."
  note "# Do not pass CancelHeaderMode: the default is warn."
  printf '\n'
  say "Then test a real cancel through the Worker once (a throwaway subscriber), or at least:"
  note "curl -s -X POST -H 'content-type: application/json' -d '{\"c\":\"cus_invalid\"}' https://$DOMAIN/api/cancel"
  pause "Backend deploy 1 done? Press Enter."
}

stage_merge_and_builds() {
  stage "Merge the PR, then connect Workers Builds"
  warn "Merging puts the redirect stubs live on kitagrawal.github.io. That points old links at $DOMAIN."
  say "Only do this once stage 5's checks passed."
  gate 7 "Is $DOMAIN serving the site from the Worker, and are you ready to merge?"
  open_url "https://github.com/kitagrawal/kitagrawal.github.io/pulls"
  step "Open the cloudflare-worker PR and merge it into main."
  pause "Merged? Press Enter."

  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
  step "Workers & Pages → appliedailetter → Settings → Builds → Connect."
  step "GitHub → install/authorise the Cloudflare app for kitagrawal/kitagrawal.github.io (read access; no token is stored in GitHub)."
  step "Production branch: main. Build command: leave EMPTY. Deploy command: npx wrangler deploy. Save."
  step "Optionally turn off builds for non-production branches."
  pause "Connected? Press Enter."
  step "Push (or re-run) one build to prove it: Builds → Retry build, or push any commit to main."
  pause "Did the build finish green? Press Enter."

  printf '\n'
  say "GitHub Pages stubs (Pages can take a few minutes after the merge):"
  local n ok=0 page
  for n in 1 2 3 4 5 6; do
    page=$(curl -sS --max-time 20 "https://kitagrawal.github.io/" 2>/dev/null || true)
    if [[ "$page" == *"location.replace('https://$DOMAIN'"* ]]; then ok=1; break; fi
    note "stub not live yet, waiting 20s (attempt $n/6)"; sleep 20
  done
  if (( ok )); then
    printf '  %s✓%s kitagrawal.github.io serves the redirect stub\n' "$GREEN" "$RESET"
  else
    printf '  %s✗%s kitagrawal.github.io is not serving the stub yet; check Settings → Pages (source: main, root)\n' "$RED" "$RESET"
  fi
  local code
  code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 20 "https://kitagrawal.github.io/unsubscribe.html?c=cus_x" 2>/dev/null || true)
  code="${code:-000}"
  [[ "$code" == 404 ]] && printf '  %s✓%s old /unsubscribe.html link lands on the 404 stub, which redirects with its query\n' "$GREEN" "$RESET" \
    || printf '  %s✗%s old /unsubscribe.html?c=... → %s (wanted 404 + stub)\n' "$RED" "$RESET" "$code"
  pause "Press Enter to continue."
}

stage_backend_enforce() {
  stage "Backend deploy 2 (enforce): only after the logs are clean"
  say "Enforce answers 403 to any cancel call without the right X-Cancel-Secret."
  local fn since count
  if (( USE_AWS )) && fn=$(cancel_function) && [[ -n "$fn" && "$fn" != None ]]; then
    since=$(( ($(date +%s) - 86400) * 1000 ))
    if confirm "Search the last 24h of the cancel Lambda's logs for warn lines (read-only)?"; then
      count=$(aws_ro logs filter-log-events --log-group-name "/aws/lambda/$fn" --start-time "$since" \
        --filter-pattern '"missing or wrong X-Cancel-Secret"' --query 'length(events)' --output text || echo "?")
      say "Warn lines in the last 24h: $count"
      note "Lines from before the Worker went live, or from your own direct tests, are expected. Look at timestamps."
      [[ "$count" == 0 ]] || warn "Any recent warn line means a caller is not using the Worker. Find it before enforcing."
    fi
  else
    note "aws logs tail /aws/lambda/<CancelFunction physical id> --since 24h --filter-pattern '\"missing or wrong\"' --profile $AWS_PROFILE_NAME --region $AWS_REGION_NAME"
  fi
  printf '\n'
  say "When no recent warn lines remain, you run deploy 2: the same sam deploy as deploy 1 with this added:"
  note "--parameter-overrides ... CancelHeaderMode=enforce      (keep your other overrides)"
  note "Rollback: deploy again with CancelHeaderMode=warn."
  pause "Backend deploy 2 done? Press Enter for the final check."

  printf '\n'
  if [[ -z "$CANCEL_API_URL" ]]; then ask_secret CANCEL_API_URL "Paste CancelApiUrl again for the enforce check (Enter to skip):" || true; fi
  if [[ -n "$CANCEL_API_URL" ]]; then
    local code
    code=$(curl_url "$CANCEL_API_URL" -o /dev/null -w '%{http_code}' -X POST -H 'content-type: application/json' --data '{"c":"cus_invalid"}' 2>/dev/null || true)
    code="${code:-000}"
    [[ "$code" == 403 ]] && printf '  %s✓%s calling AWS directly without the header → 403\n' "$GREEN" "$RESET" \
      || printf '  %s✗%s calling AWS directly without the header → %s (wanted 403)\n' "$RED" "$RESET" "$code"
  else
    note "Skipped the direct-call check."
  fi
  local body
  body=$(curl -sS --max-time 20 -X POST -H 'content-type: application/json' --data '{"c":"cus_invalid"}' "https://$DOMAIN/api/cancel" 2>/dev/null || true)
  [[ "$body" == *'"error"'* ]] && printf '  %s✓%s through the Worker a fake id still gets JSON: %s\n' "$GREEN" "$RESET" "$body" \
    || printf '  %s✗%s through the Worker: %s\n' "$RED" "$RESET" "${body:-<empty>}"
  warn "If the Worker answers 403 here, the Worker secret and the AWS field differ. Re-run stage 4."
  note "Last: do one real unsubscribe test from a letter link on https://$DOMAIN/unsubscribe.html."
  pause "Press Enter to finish."
}

STAGE_FUNCS=(stage_snapshot stage_add_zone stage_switch_ns stage_secrets stage_first_deploy stage_backend_warn stage_merge_and_builds stage_backend_enforce)
banner "appliedailetter.com: move DNS to Cloudflare and ship the Worker"
preflight
_STAGE_INDEX=$((START - 1))
for ((i = START - 1; i < TOTAL_STAGES; i++)); do "${STAGE_FUNCS[$i]}"; done
unset SHARED_SECRET CANCEL_API_URL

finish
(( ${#WORKER_SECRETS[@]} )) && note "set ${#WORKER_SECRETS[@]} Worker secret(s) this run: ${WORKER_SECRETS[*]}"
note "Rollback of the DNS move: set the old IONOS nameservers again (listed in the snapshot's NS line)."
printf '\n'
